#include <vector>
#include <algorithm>

class Solution {
public:
    int minNumberOfSemesters(int n, std::vector<std::vector<int>>& relations, int k) {
        std::vector<int> prereq(n, 0);
        for (const auto& r : relations) {
            prereq[r[1] - 1] |= (1 << (r[0] - 1));
        }
        std::vector<int> dp(1 << n, 1e8);
        dp[0] = 0;
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (dp[mask] >= 1e8) continue;
            int available = 0;
            for (int i = 0; i < n; ++i) {
                if (!(mask & (1 << i)) && (prereq[i] & mask) == prereq[i]) {
                    available |= (1 << i);
                }
            }
            for (int sub = available; sub > 0; sub = (sub - 1) & available) {
                if (__builtin_popcount(sub) <= k) {
                    dp[mask | sub] = std::min(dp[mask | sub], dp[mask] + 1);
                }
            }
        }
        return dp[(1 << n) - 1];
    }
};

import java.util.*;

class Solution {
    public int minNumberOfSemesters(int n, int[][] relations, int k) {
        int[] prereq = new int[n];
        for (int[] r : relations) {
            prereq[r[1] - 1] |= (1 << (r[0] - 1));
        }
        int[] dp = new int[1 << n];
        Arrays.fill(dp, 100000000);
        dp[0] = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[mask] >= 100000000) continue;
            int available = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0 && (prereq[i] & mask) == prereq[i]) {
                    available |= (1 << i);
                }
            }
            for (int sub = available; sub > 0; sub = (sub - 1) & available) {
                if (Integer.bitCount(sub) <= k) {
                    dp[mask | sub] = Math.min(dp[mask | sub], dp[mask] + 1);
                }
            }
        }
        return dp[(1 << n) - 1];
    }
}

var minNumberOfSemesters = function(n, relations, k) {
    const prereq = new Array(n).fill(0);
    for (const [u, v] of relations) {
        prereq[v - 1] |= (1 << (u - 1));
    }
    const dp = new Array(1 << n).fill(1e8);
    dp[0] = 0;
    function countBits(x) {
        let c = 0;
        while (x) { c += x & 1; x >>= 1; }
        return c;
    }
    for (let mask = 0; mask < (1 << n); mask++) {
        if (dp[mask] >= 1e8) continue;
        let available = 0;
        for (let i = 0; i < n; i++) {
            if (!(mask & (1 << i)) && (prereq[i] & mask) === prereq[i]) {
                available |= (1 << i);
            }
        }
        for (let sub = available; sub > 0; sub = (sub - 1) & available) {
            if (countBits(sub) <= k) {
                dp[mask | sub] = Math.min(dp[mask | sub], dp[mask] + 1);
            }
        }
    }
    return dp[(1 << n) - 1];
};
